input.command:
Write-Output '=== data/ ==='
Get-ChildItem -LiteralPath 'D:\claude\harness-on-steroids\data' -Force -ErrorAction SilentlyContinue | ForEach-Object { '{0} {1}' -f $_.Mode, $_.Name }
Write-Output '=== Local OpenAI ==='
Get-ChildItem -LiteralPath "$env:LOCALAPPDATA\OpenAI" -Force -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object -First 80 | ForEach-Object { $_.FullName.Replace($env:LOCALAPPDATA, '%LOCALAPPDATA%') }
Write-Output '=== Codex Store package top ==='
$pkg = "$env:LOCALAPPDATA\Packages\OpenAI.Codex_2p2nqsd0c76g0"
Get-ChildItem -LiteralPath $pkg -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }
Write-Output '=== Codex LocalState depth 2 ==='
Get-ChildItem -LiteralPath "$pkg\LocalState" -Force -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object -First 60 | ForEach-Object { $_.FullName.Replace($env:LOCALAPPDATA, '%LOCALAPPDATA%') }
Write-Output '=== Downloads chatgpt/openai zip json ==='
Get-ChildItem -LiteralPath "$env:USERPROFILE\Downloads" -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'chatgpt|openai|conversation|export' } | ForEach-Object { '{0} {1}' -f $_.Length, $_.Name }
Write-Output '=== Documents chatgpt/openai zip json ==='
Get-ChildItem -LiteralPath "$env:USERPROFILE\Documents" -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'chatgpt|openai|conversation|export' } | ForEach-Object { '{0} {1}' -f $_.Length, $_.Name }

$pkg = "$env:LOCALAPPDATA\Packages\OpenAI.Codex_2p2nqsd0c76g0"
Write-Output '=== Store package dirs ==='
foreach ($d in @('LocalState','LocalCache','AppData','RoamingState')) {
  $p = Join-Path $pkg $d
  if (Test-Path -LiteralPath $p) {
    Write-Output ("DIR {0}" -f $d)
    Get-ChildItem -LiteralPath $p -Force -ErrorAction SilentlyContinue | Select-Object -First 30 | ForEach-Object { '  {0}' -f $_.Name }
  } else { Write-Output ("MISSING {0}" -f $d) }
}
Write-Output '=== USERPROFILE .codex ==='
$c = Join-Path $env:USERPROFILE '.codex'
if (Test-Path -LiteralPath $c) {
  Get-ChildItem -LiteralPath $c -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }
} else { Write-Output 'missing .codex' }
Write-Output '=== typical browser Codex/ChatGPT cache dirs exist? ==='
$browser = @(
  "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default\Local Storage",
  "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Local Storage",
  "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Local Storage",
  "$env:APPDATA\Codex\web",
  "$env:LOCALAPPDATA\Codex\web",
  "$pkg\LocalCache\Local\Codex\web",
  "$pkg\LocalState\web"
)
foreach ($p in $browser) { Write-Output ("EXISTS={0} {1}" -f (Test-Path -LiteralPath $p), $p) }

Write-Output '=== .chatgpt-projects ==='
$p = Join-Path $env:USERPROFILE '.codex\.chatgpt-projects'
Get-ChildItem -LiteralPath $p -Force -ErrorAction SilentlyContinue | Select-Object -First 40 | ForEach-Object { '{0} {1}' -f $_.Mode, $_.Name }
Write-Output '=== exporter zip listing (names only) ==='
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zips = @(
  "$env:USERPROFILE\Downloads\June 2026\chatgpt-transcript-exporter-v0.1.0.zip",
  "$env:USERPROFILE\Downloads\June 2026\chatgpt-10-day-cleaner-v2.zip"
)
foreach ($z in $zips) {
  Write-Output ("ZIP {0}" -f (Split-Path $z -Leaf))
  if (Test-Path -LiteralPath $z) {
    $archive = [System.IO.Compression.ZipFile]::OpenRead($z)
    try {
      $archive.Entries | Select-Object -First 25 | ForEach-Object { '  {0} {1}' -f $_.Length, $_.FullName }
      Write-Output ("  ENTRY_COUNT={0}" -f $archive.Entries.Count)
    } finally { $archive.Dispose() }
  }
}
Write-Output '=== search Downloads June 2026 for conversations.json / chatgpt export ==='
Get-ChildItem -LiteralPath "$env:USERPROFILE\Downloads\June 2026" -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'chatgpt|openai|conversation|export' } | ForEach-Object { '{0} {1}' -f $_.Length, $_.Name }
